create extension if not exists pgcrypto;
create sequence if not exists classence_id_seq start 1;
create table profiles (id uuid primary key references auth.users(id), classence_id text unique not null default ('CCA-' || lpad(nextval('classence_id_seq')::text,4,'0')),full_name text not null,email text unique not null,role text not null check(role in ('super_admin','member')),status text not null check(status in ('invited','active','suspended')),created_at timestamptz default now(),activated_at timestamptz);
create table invitations(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id),token_hash text unique not null,expires_at timestamptz not null,used_at timestamptz,created_at timestamptz default now());
create table agreements(id uuid primary key default gen_random_uuid(),version integer unique not null,title text not null,body text not null,is_active boolean default false,created_at timestamptz default now(),created_by uuid references profiles(id));
create unique index one_active_agreement on agreements(is_active) where is_active;
create table nda_signatures(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id),agreement_id uuid references agreements(id),full_name text,email text,phone text,position text,address text,signed_date date,signature_method text check(signature_method in ('drawn','uploaded')),signature_path text,pdf_path text,ip_address text,user_agent text,email_status text default 'pending' check(email_status in ('pending','sent','delivered','failed')),brevo_message_id text,signed_at timestamptz default now(),revoked_at timestamptz,revoked_reason text);
create unique index one_valid_signature on nda_signatures(profile_id,agreement_id) where revoked_at is null;
create table meetings(id uuid primary key default gen_random_uuid(),title text not null,description text,meet_url text not null,starts_at timestamptz not null,ends_at timestamptz not null,access_opens_at timestamptz not null,access_expires_at timestamptz not null,status text default 'scheduled' check(status in ('scheduled','cancelled')),created_by uuid references profiles(id),created_at timestamptz default now(),check(access_opens_at<=starts_at and starts_at<ends_at and ends_at<=access_expires_at));
create table meeting_revocations(id uuid primary key default gen_random_uuid(),meeting_id uuid references meetings(id) on delete cascade,profile_id uuid references profiles(id),revoked_at timestamptz default now(),reason text,unique(meeting_id,profile_id));
create table access_logs(id uuid primary key default gen_random_uuid(),meeting_id uuid references meetings(id) on delete set null,profile_id uuid references profiles(id),result text check(result in ('granted','denied')),reason text,ip_address text,created_at timestamptz default now());
create table email_logs(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id),type text check(type in ('invite','nda_signed','password_reset','other')),to_email text,subject text,status text default 'queued' check(status in ('queued','sent','delivered','failed','bounced')),brevo_message_id text,error text,created_at timestamptz default now());
create table audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references profiles(id),action text,entity_type text,entity_id text,metadata jsonb default '{}',ip_address text,created_at timestamptz default now());
do $$ declare t text; begin foreach t in array array['profiles','invitations','agreements','nda_signatures','meetings','meeting_revocations','access_logs','email_logs','audit_logs'] loop execute format('alter table %I enable row level security',t); end loop; end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('signatures','signatures',false,2097152,array['image/png','image/jpeg']),('nda-pdfs','nda-pdfs',false,10485760,array['application/pdf']) on conflict(id) do update set public=false;
create or replace function activate_agreement(target uuid) returns void language plpgsql security definer set search_path=public as $$ begin perform pg_advisory_xact_lock(612345); if not exists(select 1 from agreements where id=target) then raise exception 'Agreement not found'; end if; update agreements set is_active=false where is_active; update agreements set is_active=true where id=target; end $$;
revoke all on function activate_agreement(uuid) from public,anon,authenticated;
grant execute on function activate_agreement(uuid) to service_role;
create or replace function claim_invitation(invite_hash text) returns uuid language plpgsql security definer set search_path=public as $$ declare pid uuid; begin update invitations set used_at=now() where token_hash=invite_hash and used_at is null and expires_at>now() returning profile_id into pid; return pid; end $$;
revoke all on function claim_invitation(text) from public,anon,authenticated;
grant execute on function claim_invitation(text) to service_role;
